        self.state.last_ai_update = self.state.timestamp

def _update_robot_vision(self, robot: Robot):
    """Update what a robot can see"""
    robot.last_seen_enemies = []

    for team in [Team.RED, Team.BLUE]:
        if team == robot.team:
            continue

        for other_robot in self.state.teams[team]:
            if not other_robot.is_active:
                continue

            distance = robot.position.distance_to(other_robot.position)
            if distance < robot.vision_range:
                # Add to last seen enemies
                robot.last_seen_enemies.append({
                    'id': other_robot.id,
                    'position': other_robot.position,
                    'health': other_robot.health,
                    'team': other_robot.team,
                    'distance': distance,
                    'weapon': other_robot.weapon
                })

