def _ai_choose_action(self, robot: Robot) -> Dict:
    """AI decision-making system with adaptive difficulty"""
    # Get current game context
    objectives = self.state.objectives
    enemies = robot.last_seen_enemies
    allies = []

    for team in [Team.RED, Team.BLUE]:
        if team != robot.team:
            continue
        for other_robot in self.state.teams[team]:
            if other_robot.id != robot.id and other_robot.is_active:
                allies.append(other_robot)

    # Calculate difficulty modifier
    difficulty = self.state.difficulty_level

    # AI strategy selection based on role, health, and context
    strategy_weights = {}

    # Base weights for each strategy
    strategy_weights['attack_nearest_enemy'] = 1.0
    strategy_weights['support_allies'] = 0.8
    strategy_weights['capture_objective'] = 1.2
    strategy_weights['retreat_low_health'] = 0.5
    strategy_weights['flank_enemy'] = 0.9
    strategy_weights['reposition_for_cover'] = 0.7

    # Adjust weights by robot type
    if robot.robot_type == RobotType.ASSAULT:
        strategy_weights['attack_nearest_enemy'] += 0.5
        strategy_weights['flank_enemy'] += 0.3
    elif robot.robot_type == RobotType.SUPPORT:
        strategy_weights['support_allies'] += 0.7
        strategy_weights['reposition_for_cover'] += 0.4
    elif robot.robot_type == RobotType.RECON:
        strategy_weights['flank_enemy'] += 0.6
        strategy_weights['attack_nearest_enemy'] += 0.3
    elif robot.robot_type == RobotType.TANK:
        strategy_weights['attack_nearest_enemy'] += 0.4
        strategy_weights['reposition_for_cover'] += 0.5

    # Adjust weights by difficulty level (higher difficulty = more aggressive)
    if difficulty > 1.0:
        for key in strategy_weights:
            if 'attack' in key or 'flank' in key:
                strategy_weights[key] *= (1 + (difficulty - 1.0) * 0.5)
    elif difficulty < 1.0:
        for key in strategy_weights:
            if 'retreat' in key or 'reposition' in key:
                strategy_weights[key] *= (1 + (1.0 - difficulty) * 0.5)

    # Adjust weights by health
    if robot.health < robot.max_health * 0.3:
        strategy_weights['retreat_low_health'] += 1.5
        strategy_weights['attack_nearest_enemy'] *= 0.3
        strategy_weights['flank_enemy'] *= 0.3
    elif robot.health < robot.max_health * 0.6:
        strategy_weights['retreat_low_health'] += 0.5
        strategy_weights['support_allies'] += 0.3

    # Adjust weights by objective proximity
    closest_objective = None
    min_obj_dist = float('inf')
    for obj in objectives:
        if not obj.is_active:
            continue
        dist = robot.position.distance_to(obj.position)
        if dist < min_obj_dist:
            min_obj_dist = dist
            closest_objective = obj

    if closest_objective and min_obj_dist < robot.vision_range:
        # If objective is uncaptured and robot's team doesn't own it, prioritize capture
        if closest_objective.team_ownership != robot.team and closest_objective.captured_by != robot.team:
            strategy_weights['capture_objective'] += 1.0
        # If objective is captured by enemy, prioritize attack
        elif closest_objective.team_ownership == robot.team and closest_objective.captured_by != robot.team:
            strategy_weights['attack_nearest_enemy'] += 0.7

    # Adjust for enemy density and threat
    if len(enemies) > 0:
        nearest_enemy = min(enemies, key=lambda e: e['distance'])
        if nearest_enemy['distance'] < 100:
            strategy_weights['attack_nearest_enemy'] += 0.5
            strategy_weights['flank_enemy'] += 0.3
        elif nearest_enemy['distance'] < 200:
            if robot.weapon == WeaponType.SNIPER:
                strategy_weights['attack_nearest_enemy'] += 0.8
            else:
                strategy_weights['flank_enemy'] += 0.4

    # Adjust for ally proximity and need
    if len(allies) > 0:
        nearest_ally = min(allies, key=lambda a: robot.position.distance_to(a.position))
        if nearest_ally.health < nearest_ally.max_health * 0.4:
            strategy_weights['support_allies'] += 1.0

    # Select highest-weighted strategy
    selected_strategy = max(strategy_weights.keys(), key=lambda k: strategy_weights[k])

    # Return action with context
    action = {
        'type': selected_strategy,
        'target': None,
        'priority': strategy_weights[selected_strategy],
        'difficulty': difficulty
    }

    # Set target based on strategy
    if selected_strategy == 'attack_nearest_enemy' and len(enemies) > 0:
        nearest_enemy = min(enemies, key=lambda e: e['distance'])
        action['target'] = nearest_enemy['position']
    elif selected_strategy == 'capture_objective' and closest_objective:
        action['target'] = closest_objective.position
    elif selected_strategy == 'flank_enemy' and len(enemies) > 0:
        nearest_enemy = min(enemies, key=lambda e: e['distance'])
        # Flank by moving perpendicular to enemy-robot vector
        enemy_pos = nearest_enemy['position']
        direction = robot.position - enemy_pos
        # Rotate 90 degrees for flank
        flank_dir = Position(-direction.y, direction.x).normalize()
        # Move 150 units to the side
        flank_pos = enemy_pos + (flank_dir * 150)
        # Clamp within map
        flank_pos.x = max(50, min(MAP_SIZE[0] - 50, flank_pos.x))
        flank_pos.y = max(50, min(MAP_SIZE[1] - 50, flank_pos.y))
        action['target'] = flank_pos
    elif selected_strategy == 'retreat_low_health':
        # Retreat from nearest enemy
        if len(enemies) > 0:
            nearest_enemy = min(enemies, key=lambda e: e['distance'])
            direction = robot.position - nearest_enemy['position']
            retreat_pos = robot.position + (direction.normalize() * 150)
            retreat_pos.x = max(50, min(MAP_SIZE[0] - 50, retreat_pos.x))
            retreat_pos.y = max(50, min(MAP_SIZE[1] - 50, retreat_pos.y))
            action['target'] = retreat_pos
        else:
            # General retreat to safe area
            action['target'] = Position(MAP_SIZE[0]/2, MAP_SIZE[1]/2)
    elif selected_strategy == 'reposition_for_cover':
        # Move toward nearest cover (edge of map or hazard)
        cover_positions = []
        for hazard in self.state.hazards:
            if hazard.active:
                cover_positions.append(hazard.position)
        if cover_positions:
            nearest_cover = min(cover_positions, key=lambda p: robot.position.distance_to(p))
            action['target'] = nearest_cover
        else:
            # Move toward team base
            base_pos = Position(150, 400) if robot.team == Team.RED else Position(850, 400)
            action['target'] = base_pos
    elif selected_strategy == 'support_allies' and len(allies) > 0:
        nearest_ally = min(allies, key=lambda a: robot.position.distance_to(a.position))
        if nearest_ally.health < nearest_ally.max_health * 0.5:
            action['target'] = nearest_ally.position
        else:
            # Move to support position (behind ally)
            direction = robot.position - nearest_ally.position
            support_pos = nearest_ally.position + (direction.normalize() * 80)
            action['target'] = support_pos

    # Log debug info
    if DEBUG_MODE:
        self._log_event(f"Robot {robot.id} ({robot.team.value}) selected {selected_strategy} (weight: {strategy_weights[selected_strategy]:.2f})")

    return action
